const assert = require('assert');
const crypto = require('crypto');

// Load and wait for WASM module to initialize
let libqrl;
let moduleReady = false;

before(async function() {
    this.timeout(10000); // Allow time for WASM to load
    const Module = require('./tmp/libjsqrl.js');

    // Wait for the module to be ready
    await new Promise((resolve) => {
        if (Module.calledRun) {
            libqrl = Module;
            moduleReady = true;
            resolve();
        } else {
            Module.onRuntimeInitialized = () => {
                libqrl = Module;
                moduleReady = true;
                resolve();
            };
        }
    });
});

// TODO: Move this to another file with all the helper functions

function ToArray(vec) {
    let arr = new Uint8Array(vec.size());
    for (let i = 0; i < vec.size(); i++) {
        arr[i] = vec.get(i);
    }
    return arr;
}

function ToUint8Vector(arr) {
    let vec = new libqrl.Uint8Vector();
    for (let i = 0; i < arr.length; i++) {
        vec.push_back(arr[i])
    }
    return vec;
}

function bytesToHex (byteArray) {
    return Array.from(byteArray, function (byte) {
      return ('00' + (byte & 0xFF).toString(16)).slice(-2);
    }).join('');
  };

   function binaryToBytes (convertMe) {
    const thisBytes = new Uint8Array(convertMe.size());
    for (let i = 0; i < convertMe.size(); i += 1) {
      thisBytes[i] = convertMe.get(i);
    }
    return thisBytes;
  };

